command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="74550ff2c67633371d1c3ad2e266c32a7e7c8ed1";$candidate="ffb0401841a5e58b4786a8c758961016b870bde0";$branch="work/unc-network-metadata-sort-20261007"
Set-Location -LiteralPath $repo
& git fetch origin main $branch --no-tags --prune
if($LASTEXITCODE -ne 0){throw "network metadata diagnostic fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne $main){throw "main moved before network metadata diagnostic"}
if((& git rev-parse ("refs/remotes/origin/"+$branch)).Trim() -ne $candidate){throw "network metadata diagnostic candidate moved"}
$temp=Join-Path $env:RUNNER_TEMP ("fly-network-metadata-diag-"+$env:GITHUB_RUN_ID)
if(Test-Path -LiteralPath $temp){Remove-Item -LiteralPath $temp -Recurse -Force}
try{
 & git worktree add --detach $temp $candidate
 if($LASTEXITCODE -ne 0){throw "network metadata diagnostic worktree add failed"}
 Set-Location -LiteralPath $temp
 & .\build.bat Release
 if($LASTEXITCODE -ne 0){throw "network metadata diagnostic Release materialization failed"}
 & python -u -X utf8 .\tests\winui\test_metadata_sort_gui.py --configuration Release --force-isolated-metadata --items 25 --diagnose-first-sort
 if($LASTEXITCODE -ne 0){throw "network metadata diagnostic harness failed"}
 Write-Host "NETWORK_METADATA_DIAGNOSTIC_SMALL_FIXTURE=PASS"
 Write-Host "NETWORK_METADATA_REUSED_RELEASE_BUILD_EVIDENCE=37559970803"
}finally{
 Set-Location -LiteralPath $repo
 if(Test-Path -LiteralPath $temp){& git worktree remove --force $temp}
 & git worktree prune
}
